ruleBookInfo.intro:
@js:
var html = '' + result;
var intro = '';
var m = html.match(/<li class="mulu"><a href="([^"]+)"/);
if (m) {
  var page = '' + java.ajax(m[1]);
  var cm = page.match(/<article[^>]*article-content[^>]*>([\s\S]*?)<\/article>/);
  if (cm) {
    var t = cm[1].replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/　/g, ' ').replace(/[ \t]+\n/g, '\n').replace(/\n{2,}/g, '\n').replace(/^\s+|\s+$/g, '');
    if (t.indexOf('作者') >= 0) {
      var cut = t.length;
      var marks = ['Tips', '传送门', '如果觉得', '哦豁', '上一页'];
      for (var k = 0; k < marks.length; k++) {
        var ix = t.indexOf(marks[k]);
        if (ix > 0 && ix < cut) { cut = ix; }
      }
      var chs = ['第1章', '第一章', '第01章', '第001章', '楔子', '序章', 'Chapter 1'];
      for (var j = 0; j < chs.length; j++) {
        var cx = t.indexOf(chs[j]);
        if (cx > 50 && cx < cut) { cut = cx; }
      }
      intro = t.substring(0, cut);
      if (cut >= t.length && intro.length > 1000) {
        var dot = intro.lastIndexOf('。', 1000);
        if (dot > 200) { intro = intro.substring(0, dot + 1); }
      }
      intro = intro.replace(/\s+$/g, '').replace(/[=\-*_~—\s]+$/g, '');
    }
  }
}
if (!intro) {
  var ps = html.match(/<p>([\s\S]*?)<\/p>/g);
  if (ps && ps.length > 1) {
    intro = ps[1].replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/^\s+|\s+$/g, '');
  }
}
intro
